contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint256 reqAmount,
        uint256 reqInterest,
        uint256 reqLoanToCollateral,
        uint256 reqDuration,
        bool repayDirect
    ) public {
        require(reqAmount > 0);
        require(reqLoanToCollateral > 0);
        require(reqDuration > 0);

        uint256 reqID = c.requestLoan(reqAmount, reqInterest, reqLoanToCollateral, reqDuration); if (__ESBMC_reverted()) return;
        c.clearRequest(reqID, repayDirect, false); if (__ESBMC_reverted()) return;

        bool reverted;
        c.clearRequest(reqID, repayDirect, false); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted);
    }

    receive() external payable {}
}

