pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqAmount, uint256 reqInterest, uint256 reqLoanToCollateral, uint256 reqDuration, bool repayDirect) internal {
        vm.assume(reqAmount > 0);
        vm.assume(reqLoanToCollateral > 0);
        vm.assume(reqDuration > 0);
        uint256 reqID;
        try c.requestLoan(reqAmount, reqInterest, reqLoanToCollateral, reqDuration) returns (uint256 __r) { reqID = __r; } catch { return; }
        try c.clearRequest(reqID, repayDirect, false) {} catch { return; }
        bool reverted;
        try c.clearRequest(reqID, repayDirect, false) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 reqAmount, uint256 reqInterest, uint256 reqLoanToCollateral, uint256 reqDuration, bool repayDirect) public {
        _run(reqAmount, reqInterest, reqLoanToCollateral, reqDuration, repayDirect);
    }

    receive() external payable {}
}
